const fs=require('fs'),path=require('path');
const dir='Backend-Import/oekoinvest_app/oekoinvest_app/plattform/doctype';
const rows=[];
for(const d of fs.readdirSync(dir)){
  const f=path.join(dir,d,d+'.json');
  if(!fs.existsSync(f))continue;
  let j;try{j=JSON.parse(fs.readFileSync(f,'utf8'))}catch(e){console.log('PARSE-FEHLER',f,e.message);continue}
  const fields=j.fields||[];
  const byName=Object.fromEntries(fields.map(x=>[x.fieldname,x]));
  const probs=[];
  // status/date/link fields without index
  for(const fl of fields){
    const n=fl.fieldname||'';
    if((n==='status'||n==='email'||n==='e_mail')&&!fl.search_index&&!fl.in_standard_filter)probs.push('kein Index/Filter: '+n);
  }
  if(!j.track_changes)probs.push('track_changes=0');
  if(j.field_order && fields.length!==j.field_order.length)probs.push('field_order!=fields ('+j.field_order.length+' vs '+fields.length+')');
  // fields in field_order missing in fields
  const fn=new Set(fields.map(x=>x.fieldname));
  const miss=(j.field_order||[]).filter(x=>!fn.has(x));
  if(miss.length)probs.push('field_order fehlt in fields: '+miss.join(','));
  const extra=fields.filter(x=>j.field_order&&!j.field_order.includes(x.fieldname)).map(x=>x.fieldname);
  if(extra.length)probs.push('fields fehlt in field_order: '+extra.join(','));
  // Link options existing?
  if(probs.length)rows.push(d+': '+probs.join(' | '));
}
console.log(rows.join('\n'));console.log('TOTAL',rows.length);
