1	// src/lib/plattform/backend/demo/datenschutz.js
2	//
3	// Compliance – Datenschutz & Geldwäsche im Demo-Backend (Referenz für Frappe plattform/api/datenschutz.py):
4	//   Betroffenenanfragen Art. 15–21 DSGVO (Frist 1 Monat, Verlängerung, Export, Anonymisierung bei Löschersuchen),
5	//   interne Verdachtsfälle (ohne Versand an die Meldestelle), VVT-Export, Löschkonzept, SLA der KYC-Warteschlange.
6	// Daten unter db.dsgvo = { v, anfragen[], verdacht[] }.
7	//
8	// Rechte (jede Operation prüft selbst):
9	//   Anfragen     lesen: Bereich „compliance“ ≥ 1 (Leitung, Compliance); schreiben = 2 (Compliance)
10	//   Verdacht     NUR Unterrolle mit „compliance“ = 2 (auch Leitung sieht keine Verdachtsakten – Need-to-know);
11	//                intern melden (verdachtMelden) darf jedes Backoffice-Konto, sieht die Akte danach aber nicht
12	//   VVT          lesen: „compliance“ ≥ 1
13	
14	import { PlattformFehler, konflikt, nichtGefunden, ungueltig, verboten } from "../../fehler";
15	import * as v from "../../validierung";
16	import * as C from "../../compliance/index.js";
17	import { darfLesen, darfSchreiben } from "../../rechte";
18	import { intern } from "../demo";
19	import { aendern, lesen } from "./speicher";
20	import { jetzt, neueId, sha256 } from "./hilfen";
21	import { datenExport } from "./sicherheit";
22	
23	const { benachrichtigen, protokoll, nutzerById, nameVon } = intern;
24	
25	const istAdmin = (n) => !!n?.rollen?.includes("admin");
26	const angemeldet = (n) => {
27	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
28	};
29	function leseNoetig(n) {
30	  angemeldet(n);
31	  if (!istAdmin(n) || !darfLesen(n, "compliance")) throw verboten("Nur für Compliance und Leitung.");
32	}
33	function schreibNoetig(n) {
34	  angemeldet(n);
35	  if (!istAdmin(n) || !darfSchreiben(n, "compliance")) throw verboten("Nur für die Backoffice-Rolle „Compliance“.");
36	}
37	const verdachtNoetig = schreibNoetig; // Verdachtsakten: nur Compliance (Geldwäschebeauftragte/r und Vertretung)
38	
39	const heute = () => new Intl.DateTimeFormat("sv-SE", { timeZone: "Europe/Vienna" }).format(new Date());
40	
41	async function bereit() {
42	  let db = await lesen();
43	  if (!db.dsgvo) {
44	    await aendern((d) => {
45	      d.dsgvo ||= { v: 1, anfragen: [], verdacht: [] };
46	    });
47	    db = await lesen();
48	  }
49	  return db;
50	}
51	const aendernBereit = async (fn) => {
52	  await bereit();
53	  return aendern((db) => {
54	    db.dsgvo ||= { v: 1, anfragen: [], verdacht: [] };
55	    return fn(db);
56	  });
57	};
58	
59	const compliancePersonen = (db) => db.nutzer.filter((u) => u.aktiv && u.rollen?.includes("admin") && String(u.backofficeRollen || "").split(",").map((x) => x.trim()).includes("compliance"));
60	
61	function aufgabe(db, { titel, beschreibung, faelligAm, zustaendigId, vonId }) {
62	  db.aufgaben.push({ id: neueId("AF"), titel: v.text(titel, 160), beschreibung: v.text(beschreibung, 500), faelligAm, zustaendigId, bezugArt: null, bezugId: null, status: "offen", erstelltVon: vonId, erstelltAm: jetzt(), erledigtAm: null, erledigtVon: null, erinnertAm: null });
63	}
64	
65	// ================================================================ Betroffenenanfragen (DSGVO)
66	
67	function anfrageAusgabe(db, a, h = heute()) {
68	  const f = C.dsFristStatus(a, h);
69	  return {
70	    ...a,
71	    artLabel: C.DS_ARTEN[a.art]?.label, norm: C.DS_ARTEN[a.art]?.norm, statusLabel: C.DS_STATUS[a.status]?.label, statusTon: C.DS_STATUS[a.status]?.ton,
72	    frist: f.frist, restTage: f.restTage, ampel: f.ampel, ueberfaellig: !!f.ueberfaellig,
73	    konto: a.kontoId ? (() => { const u = nutzerById(db, a.kontoId); return u ? { id: u.id, email: u.email, name: nameVon(db, u.id), geloescht: !!u.geloeschtAm } : null; })() : null,
74	    zustaendig: a.zustaendigId ? nameVon(db, a.zustaendigId) : "",
75	    antwortEntwurf: C.dsAntwortEntwurf(a, { frist: f.frist }),
76	    exportVerfuegbar: !!C.DS_ARTEN[a.art]?.export && !!a.kontoId,
77	  };
78	}
79	
80	export async function dsUebersicht(n, { status = "offen" } = {}) {
81	  leseNoetig(n);
82	  const db = await bereit();
83	  const h = heute();
84	  const alle = db.dsgvo.anfragen.map((a) => anfrageAusgabe(db, a, h));
85	  const liste = alle.filter((a) => (status === "alle" ? true : status === "offen" ? C.DS_OFFEN.includes(a.status) : a.status === status)).sort((a, b) => String(a.frist).localeCompare(String(b.frist)));
86	  return {
87	    heute: h,
88	    darfSchreiben: darfSchreiben(n, "compliance"),
89	    kennzahlen: {
90	      offen: alle.filter((a) => C.DS_OFFEN.includes(a.status)).length,
91	      faellig7: alle.filter((a) => a.ampel === "gelb").length,
92	      ueberfaellig: alle.filter((a) => a.ueberfaellig).length,
93	      erledigt12m: alle.filter((a) => a.status === "erledigt" && String(a.erledigtAm || "") >= new Date(Date.now() - 365 * 86400e3).toISOString()).length,
94	    },
95	    anfragen: liste,
96	    arten: C.DS_ARTEN,
97	    loeschkonzept: C.LOESCHKLASSEN,
98	  };
99	}
100	
101	/** Neue Anfrage erfassen: { art, eingangAm, land, name, email, kontoId?, kanal, beschreibung, vorgangId? } */
102	export async function dsAnlegen(n, d = {}) {
103	  schreibNoetig(n);
104	  const art = v.auswahl(d.art, C.DS_ARTEN, "");
105	  if (!art) throw ungueltig("Bitte die Art der Anfrage wählen.");
106	  const h = heute();
107	  const eingang = /^\d{4}-\d{2}-\d{2}$/.test(String(d.eingangAm || "")) ? d.eingangAm : h;
108	  if (eingang > h) throw ungueltig("Das Eingangsdatum darf nicht in der Zukunft liegen.");
109	  if (eingang < C.plusMonate(h, -12)) throw ungueltig("Eingang älter als 12 Monate – bitte prüfen.");
110	  const name = v.text(d.name, 120);
111	  const email = d.email ? v.email(d.email) : "";
112	  if (name.length < 2) throw ungueltig("Bitte den Namen der betroffenen Person angeben.");
113	  return aendernBereit((db) => {
114	    let konto = d.kontoId ? nutzerById(db, v.kennung(d.kontoId)) : null;
115	    if (d.kontoId && !konto) throw nichtGefunden("Konto nicht gefunden.");
116	    if (!konto && email) konto = db.nutzer.find((u) => u.email === email) || null;
117	    const a = {
118	      id: neueId("DS"), art, land: v.auswahl(d.land, { AT: 1, DE: 1, CH: 1 }, "AT"), eingangAm: eingang, kanal: v.auswahl(d.kanal, { portal: 1, email: 1, brief: 1, telefon: 1, sonstiges: 1 }, "email"),
119	      name, email, kontoId: konto?.id || null, beschreibung: v.mehrzeilig(d.beschreibung, 2000), vorgangId: v.kennung(d.vorgangId) || null,
120	      status: "eingegangen", zustaendigId: n.id, identitaet: null, verlaengertAm: null, verlaengerungsgrund: "", begruendung: "", ergebnis: "", loeschErgebnis: "", exportAm: null, exportSha: "",
121	      erfasstAm: jetzt(), erfasstVon: n.id, erledigtAm: null, verlauf: [{ am: jetzt(), vonId: n.id, text: `Anfrage erfasst (${C.DS_ARTEN[art].label}, Eingang ${eingang.split("-").reverse().join(".")}, Kanal ${d.kanal || "email"})` }],
122	    };
123	    db.dsgvo.anfragen.unshift(a);
124	    const frist = C.dsFrist(eingang, { land: a.land });
125	    aufgabe(db, { titel: `DSGVO ${C.DS_ARTEN[art].label}: ${name} (${a.id})`, beschreibung: `Frist bis ${frist.split("-").reverse().join(".")} (${C.DS_ARTEN[art].norm}, Art. 12 Abs. 3 DSGVO). Identität plausibilisieren, bearbeiten, Antwort dokumentieren.`, faelligAm: [h, new Date(new Date(`${frist}T00:00:00Z`).getTime() - 7 * 86400e3).toISOString().slice(0, 10)].sort().pop(), zustaendigId: n.id, vonId: n.id });
126	    if (konto) benachrichtigen(db, konto, { art: "nachricht", titel: "Ihre Datenschutzanfrage ist eingegangen", text: `Wir bearbeiten Ihre Anfrage (${C.DS_ARTEN[art].label}) und antworten bis spätestens ${frist.split("-").reverse().join(".")}.`, link: "/portal/profil", objektArt: "nutzer", objektId: konto.id }, { mailBetreff: "Eingang Ihrer Datenschutzanfrage – ÖkoInvest", mailText: `Ihre Datenschutzanfrage ist bei uns eingegangen. Wir beantworten sie bis spätestens ${frist.split("-").reverse().join(".")}.` });
127	    protokoll(db, n, "dsgvo_anfrage", "dsgvo", a.id, `${C.DS_ARTEN[art].label} erfasst (Frist ${frist})${konto ? ` für Konto ${konto.id}` : ""}`);
128	    return anfrageAusgabe(db, a);
129	  });
130	}
131	
132	/** Aktion: Übergang (identitaet_anfordern|identitaet_bestaetigen|verlaengern|erledigen|ablehnen) oder konto_verknuepfen|anonymisieren */
133	export async function dsAktion(n, id, d = {}) {
134	  schreibNoetig(n);
135	  return aendernBereit((db) => {
136	    const a = db.dsgvo.anfragen.find((x) => x.id === v.kennung(id));
137	    if (!a) throw nichtGefunden("Anfrage nicht gefunden.");
138	    const h = heute();
139	    const log = (text) => a.verlauf.push({ am: jetzt(), vonId: n.id, text: v.text(text, 300) });
140	    if (d.aktion === "konto_verknuepfen") {
141	      if (!C.DS_OFFEN.includes(a.status)) throw konflikt("Die Anfrage ist abgeschlossen.");
142	      const u = db.nutzer.find((x) => x.id === v.kennung(d.kontoId) || (d.email && x.email === String(d.email).trim().toLowerCase()));
143	      if (!u) throw nichtGefunden("Kein Konto mit dieser Kennung/E-Mail.");
144	      a.kontoId = u.id;
145	      log(`Konto ${u.id} verknüpft`);
146	    } else if (d.aktion === "anonymisieren") {
147	      if (a.art !== "loeschung") throw konflikt("Anonymisierung nur bei Löschersuchen.");
148	      if (!["in_bearbeitung", "verlaengert"].includes(a.status)) throw konflikt("Erst nach bestätigter Identität.");
149	      if (!["LÖSCHEN", "LOESCHEN"].includes(String(d.bestaetigung || "").trim().toUpperCase())) throw ungueltig("Bitte mit dem Wort LÖSCHEN bestätigen.");
150	      if (!v.wahr(d.aufbewahrungGeprueft)) throw ungueltig("Bitte bestätigen, dass Aufbewahrungspflichten (Belege, GwG, Verträge) geprüft sind – betroffene Unterlagen bleiben gesperrt erhalten.");
151	      const u = nutzerById(db, a.kontoId);
152	      if (!u) throw konflikt("Kein Konto verknüpft.");
153	      if (u.geloeschtAm) throw konflikt("Das Konto ist bereits anonymisiert.");
154	      anonymisieren(db, n, u, a);
155	      a.loeschErgebnis = "geloescht";
156	      log(`Konto ${u.id} anonymisiert und gesperrt; Unterlagen mit Aufbewahrungspflicht bleiben gesperrt erhalten`);
157	    } else {
158	      const pruefung = C.dsUebergang(a, d.aktion, d, h);
159	      if (!pruefung.ok) throw konflikt(pruefung.fehler);
160	      const vorher = a.status;
161	      a.status = pruefung.nach;
162	      if (d.aktion === "identitaet_anfordern") a.identitaet = { status: "angefordert", notiz: v.text(d.notiz, 300), am: jetzt() };
