178	/** Anonymisierung eines Kontos auf Löschersuchen (wie Selbstlöschung in sicherheit.kontoLoeschen, ohne Passwort) */
179	function anonymisieren(db, n, u, a) {
180	  if (u.rollen?.includes("admin")) throw konflikt("Backoffice-Konten werden über die Nutzerverwaltung (Leitung) entfernt.");
181	  const mitglied = (db.mitgliedschaften || []).filter((m) => m.nutzerId === u.id && m.rolle === "inhaber").filter((m) => db.mitgliedschaften.some((x) => x.organisationId === m.organisationId && x.nutzerId !== u.id));
182	  if (mitglied.length) throw konflikt("Das Konto ist Inhaber einer Organisation mit weiteren Mitgliedern – Inhaberschaft zuerst übertragen lassen.");
183	  for (const m of (db.mitgliedschaften || []).filter((x) => x.nutzerId === u.id && x.rolle === "inhaber")) {
184	    for (const liste of [db.flaechen, db.projekte, db.interessen]) for (const o of liste || []) if (o.organisationId === m.organisationId) o.organisationId = null;
185	    db.organisationen = (db.organisationen || []).filter((o) => o.id !== m.organisationId);
186	    db.einladungen = (db.einladungen || []).filter((e) => e.organisationId !== m.organisationId);
187	  }
188	  db.mitgliedschaften = (db.mitgliedschaften || []).filter((m) => m.nutzerId !== u.id);
189	  const entwuerfeF = (db.flaechen || []).filter((f) => f.nutzerId === u.id && f.status === "entwurf" && !f.organisationId).map((f) => f.id);
190	  const entwuerfeP = (db.projekte || []).filter((p) => p.anbieterId === u.id && p.status === "entwurf" && !p.organisationId).map((p) => p.id);
191	  db.flaechen = (db.flaechen || []).filter((f) => !entwuerfeF.includes(f.id));
192	  db.projekte = (db.projekte || []).filter((p) => !entwuerfeP.includes(p.id));
193	  const alteEmail = u.email;
194	  db.einladungen = (db.einladungen || []).filter((e) => e.email !== alteEmail);
195	  for (const s of ["zweiFaktor", "sitzungen", "geraete", "anmeldungen", "tokens", "benachrichtigungen"]) db[s] = (db[s] || []).filter((x) => x.nutzerId !== u.id);
196	  if (db.anmeldeSperren) delete db.anmeldeSperren[alteEmail];
197	  Object.assign(u, {
198	    email: `geloescht-${u.id.toLowerCase()}@geloescht.invalid`, vorname: "Gelöschtes", nachname: "Konto", firma: "", telefon: "", passwortHash: null,
199	    aktiv: false, emailBestaetigt: false, suchprofil: null, komfort: null, mailEinstellungen: null, sitzungVersion: (u.sitzungVersion || 0) + 1, geloeschtAm: jetzt(), geloeschtDurch: `DSGVO ${a.id}`,
200	  });
201	  a.email = a.email ? `${a.email[0]}•••@${a.email.split("@")[1] || ""}` : "";
202	  protokoll(db, n, "konto_geloescht", "nutzer", u.id, `Konto anonymisiert auf Löschersuchen ${a.id} (${entwuerfeF.length + entwuerfeP.length} Entwürfe entfernt)`);
203	}
