163	/** Quadratmeter mit deutschen Tausenderpunkten („12.345“) oder Dezimalkomma */
164	export function m2Zahl(w) {
165	  if (w === undefined || w === null || w === "") return null;
166	  let s = String(w).replace(/\s|m²|m2/gi, "");
167	  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) s = s.replace(/\./g, "");
168	  const n = v.zahl(s, { min: 1, max: 100000000, stellen: 0 });
169	  return n;
170	}
