172	/** Ein Flurstück bereinigen (ohne Fehlerprüfung) */
173	function flurstueckRoh(x, land) {
174	  const def = FLURSTUECK_FELDER[land] || FLURSTUECK_FELDER.DE;
175	  const fs = {};
176	  for (const k of FS_SCHLUESSEL) {
177	    if (!def[k]) continue;
178	    if (k === "m2") {
179	      fs.m2 = m2Zahl(x?.m2);
180	      continue;
181	    }
182	    let w = v.text(x?.[k], k === "gemarkung" || k === "grundbuch" ? 80 : 30);
183	    if (k === "egrid") w = w.replace(/\s/g, "").toUpperCase();
184	    if (k === "nummer" || k === "gemarkungNr" || k === "blatt" || k === "flur") w = w.replace(/\s/g, "");
185	    fs[k] = w;
186	  }
187	  return fs;
188	}
189	
190	const fsLeer = (fs) => !FS_SCHLUESSEL.some((k) => (k === "m2" ? fs.m2 : fs[k]));
191	
192	/** Formatfehler eines bereinigten Flurstücks: [{feld, text}] */
193	export function flurstueckFehler(fs, land) {
194	  const def = FLURSTUECK_FELDER[land] || FLURSTUECK_FELDER.DE;
195	  const fehler = [];
196	  for (const [k, d] of Object.entries(def)) {
197	    const w = fs[k];
198	    if (k === "m2") {
199	      continue;
200	    }
201	    if (!w) {
202	      if (d.pflicht) fehler.push({ feld: k, text: `${d.label} fehlt` });
203	      continue;
204	    }
205	    if (d.muster && !d.muster.test(w)) fehler.push({ feld: k, text: d.fehler });
206	  }
207	  if (land === "DE" && !fs.gemarkung && !fs.gemarkungNr) fehler.push({ feld: "gemarkung", text: "Gemarkung (Name oder Nummer) fehlt" });
208	  if (land === "CH" && !fs.gemarkung && !fs.gemarkungNr && !fs.egrid) fehler.push({ feld: "gemarkung", text: "Gemeinde fehlt" });
209	  return fehler;
210	}
