212	/**
213	 * Flurstücke bereinigen und prüfen. Leere Zeilen fallen weg.
214	 * Liefert { flurstuecke, fehler: [{index, feld, text}] } – der Server wirft bei Fehlern 422.
215	 */
216	export function flurstueckePruefen(liste, land = "DE") {
217	  const flurstuecke = [];
218	  const fehler = [];
219	  if (!Array.isArray(liste)) return { flurstuecke, fehler };
220	  liste.slice(0, 50).forEach((x) => {
221	    const fs = flurstueckRoh(x || {}, land);
222	    if (fsLeer(fs)) return;
223	    const i = flurstuecke.length;
224	    for (const f of flurstueckFehler(fs, land)) fehler.push({ index: i, ...f });
225	    flurstuecke.push(fs);
226	  });
227	  return { flurstuecke, fehler };
228	}
