230	/** Anzeigetext eines Flurstücks je Land */
231	export function flurstueckText(fs, land = "DE") {
232	  if (!fs) return "";
233	  if (land === "AT") return [fs.gemarkung && `KG ${fs.gemarkung}`, fs.gemarkungNr && `(${fs.gemarkungNr})`, fs.nummer && `Gst.-Nr. ${fs.nummer}`, fs.blatt && `EZ ${fs.blatt}`].filter(Boolean).join(" ");
234	  if (land === "CH") return [fs.gemarkung, fs.nummer && `Parzelle ${fs.nummer}`, fs.egrid && `E-GRID ${fs.egrid}`].filter(Boolean).join(" · ");
235	  return [fs.gemarkung, fs.flur && `Flur ${fs.flur}`, fs.nummer && `Flst. ${fs.nummer}`, fs.blatt && `(${fs.grundbuch ? `${fs.grundbuch} ` : ""}Bl. ${fs.blatt})`].filter(Boolean).join(" ");
236	}
