238	/**
239	 * Summenfläche der Flurstücke gegen die angegebene Größe plausibilisieren.
240	 * Liefert { summeHa, vollstaendig, abweichung, stufe: ok|hinweis|warnung|fehler|null, text }
241	 */
242	export function summenPruefung(flurstuecke = [], ha) {
243	  const mit = flurstuecke.filter((f) => Number(f?.m2) > 0);
244	  if (!mit.length) return { summeHa: null, vollstaendig: false, abweichung: null, stufe: null, text: "" };
245	  const summeHa = Math.round((mit.reduce((s, f) => s + Number(f.m2), 0) / 10000) * 10000) / 10000;
246	  const vollstaendig = mit.length === flurstuecke.length;
247	  const angabe = Number(ha) > 0 ? Number(ha) : null;
248	  const fmtHa = (x) => `${x.toLocaleString("de-DE", { maximumFractionDigits: 2 })} ha`;
249	  if (!vollstaendig) {
250	    return { summeHa, vollstaendig, abweichung: null, stufe: "hinweis", text: `Nur für ${mit.length} von ${flurstuecke.length} Flurstücken ist die Katasterfläche angegeben (${fmtHa(summeHa)}). Für die Plausibilisierung bitte bei allen ergänzen.` };
251	  }
252	  if (!angabe) return { summeHa, vollstaendig, abweichung: null, stufe: "hinweis", text: `Summe laut Kataster: ${fmtHa(summeHa)}.` };
253	  const abweichung = (angabe - summeHa) / summeHa;
254	  if (abweichung > 0.1) {
255	    return { summeHa, vollstaendig, abweichung, stufe: "fehler", text: `Die angegebene Größe (${fmtHa(angabe)}) übersteigt die Summe der Flurstücke laut Kataster (${fmtHa(summeHa)}) um mehr als 10 %. Bitte Größe oder Flurstücke korrigieren.` };
256	  }
257	  if (abweichung > 0.02) {
258	    return { summeHa, vollstaendig, abweichung, stufe: "warnung", text: `Die angegebene Größe liegt etwas über der Katasterfläche (${fmtHa(summeHa)}). Bitte prüfen – maßgeblich ist das Kataster.` };
259	  }
260	  if (abweichung < -0.1) {
261	    return { summeHa, vollstaendig, abweichung, stufe: "hinweis", text: `Sie bieten offenbar eine Teilfläche an (${fmtHa(angabe)} von ${fmtHa(summeHa)}). Bitte die Teilfläche im Lageplan markieren – sie wird später vermessen.` };
262	  }
263	  return { summeHa, vollstaendig, abweichung, stufe: "ok", text: `Größe passt zur Katasterfläche (${fmtHa(summeHa)}).` };
264	}
